// GENERATED by script/spec.ts from crates/pxl/core/src/memory.json — do not edit.
//
// The core memory: the page everything in it is counted in, where the front's
// ranges begin, and how much a device is asked to reserve.
//
// Every one of these is read by more than one language or by more than one
// stage of the build, which is why they are here rather than in any of them:
//
//   crates/pxl/core/src/memory.rs        the map — the fixed ranges and the heap
//   crates/pxl/wasm/build.rs             the front — the linker flags and the
//                                        ring addresses it writes for the module
//   apps/web/src/wasm/core_memory.ts     the reservation the shell makes
//
// The one before this was three copies: the shell picked the reservation, the
// kernel wrote the same number down beside a comment saying it was not read
// here, and nothing compared them — so a shell that asked for too little
// instantiated fine and the kernel asserted its way out of it a moment later,
// long after the point where the mistake could be named.

import type { u32 } from "@xpute/core/kit/word.ts";

/** What every range in the memory begins on, and the smallest block the heap's
 * buddy hands out (xpute ds/buddy_tree.rs's MIN_ALLOC, which memory.rs asserts
 * against this). A ring slot's payload is one of these too.
 *
 * A borrowed analogy rather than a hardware number: this kernel is handed one
 * fixed range, addresses it with 32-bit offsets and has no MMU, which is the
 * situation a 32-bit machine was in, and 4 KiB is what that situation settled
 * on. The host's own page size is deliberately ignored — 16 KiB on Apple
 * silicon, 4 KiB on x86-64, 64 KiB for a WebAssembly page — since none of the
 * three is visible here or acts on anything decided here
 * (issue/20260916-the-page-table-the-pool-did-not-need.md). */
export const PAGE_BYTES: u32 = 4096 as number;

/** The stack, at the bottom of the memory. Not a choice made here: rustc passes
 * `-z stack-size=1048576` and `--stack-first` to wasm-ld for
 * wasm32-unknown-unknown, and this is that number written where the ranges
 * above it are placed against it.
 *
 * First so that an overflow goes below zero, wraps as an unsigned 32-bit
 * address and lands outside the memory, which traps. With the stack after the
 * data it would write over `.data` silently instead. There is no MMU here and
 * so no guard page: the wraparound is the whole of the protection. */
export const STACK_BYTES: u32 = 1048576 as number;

/** Messages a ring holds, and so payloads: one a slot
 * (issue/20260917-the-ring-a-slot-and-its-payload.md). A power of two, which
 * the ring checks, since a position is taken modulo it by masking. */
export const RING_CAPACITY: u32 = 2048 as number;

/** Where the rings' descriptors begin: the first page past the stack. */
export const RING_DESC_AT: u32 = 1048576 as number;

/** Where the rings' payloads begin. Past the descriptors with room to spare, so
 * that a ring deepened does not move the payloads of the ring before it. */
export const RING_SLOT_AT: u32 = 2097152 as number;

/** Where the linker may start placing `.rodata`, `.data` and `.bss` — passed to
 * wasm-ld as `--global-base`, which is the only way to keep it out of the range
 * the rings take.
 *
 * A round number rather than wherever the rings happen to end, so the two
 * ranges grow without moving each other: the rings have everything below it and
 * the module's own data everything above. */
export const GLOBAL_BASE: u32 = 33554432 as number;

/** What the module's whole front may take: the stack, the rings and everything
 * the linker places. **Nothing is laid out at it.** Where the module's data
 * ends is the linker's answer (`__data_end`) and the fixed ranges begin at the
 * page past it, so a byte of this that goes unused goes to the heap.
 *
 * It exists so that "does the terrain still fit a phone" stays a compile-time
 * question. Half of the answer is a link-time number; against a ceiling the
 * question splits in two and both halves are cheap — the fixed ranges against
 * this when the kernel compiles, and the linker against this when the module
 * boots. */
export const MODULE_CEILING: u32 = 67108864 as number;

/** What a device's memory is counted in, and all that is left of the regions the
 * pools used to cut: a reservation is a whole number of these and the bytes
 * past the last one are left out. */
export const REGION_BYTES: u32 = 67108864 as number;

/** What a handheld is asked to reserve. Half of the desktop's, because a
 * reservation is committed lazily by the OS but JavaScriptCore reports the
 * whole of it as the page's JavaScript memory — a Safari heap timeline read it
 * as one ArrayBuffer.
 *
 * Also the floor the module declares to the engine (`--initial-memory`), so a
 * shell that asks for less fails to instantiate rather than booting into a
 * kernel with nowhere to put the terrain. */
export const PHONE_BYTES: u32 = 536870912 as number;

/** What everything else is asked to reserve. */
export const DESKTOP_BYTES: u32 = 1073741824 as number;
